import { buildAuditJson } from './auditJson';
import { deployEvents } from './deploymentService';

function PipelineAuditEventsGeneratorPage() {
  const [showReviewPage, setShowReviewPage] = useState(false);
  const validateGeneratedEvents = () => {
    toast.success('Audit event inputs are valid');
    setShowReviewPage(true);
  };
  const copyJson = async () => {
    await navigator.clipboard.writeText(buildAuditJson());
    toast.success('JSON copied');
    setShowReviewPage(true);
  };
  return showReviewPage ? <section><h2>Session Summary</h2></section> : <><Button onPress={validateGeneratedEvents}>Validate</Button><Button onPress={copyJson}>Copy JSON</Button></>;
}

export default PipelineAuditEventsGeneratorPage;
